PRAGMA foreign_keys=ON;
CREATE TABLE parents ( id INTEGER PRIMARY KEY AUTOINCREMENT, identity_key TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', telegram_chat_id TEXT, chat_verified INTEGER NOT NULL DEFAULT 0, consent INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE students ( id INTEGER PRIMARY KEY AUTOINCREMENT, parent_id INTEGER NOT NULL REFERENCES parents(id) ON DELETE CASCADE, full_name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ( 'pending_current', 'current', 'new_lead', 'testing_only' )), created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(parent_id, full_name) );